# --- 새 상품 저장 (id 가 null) ---

Book book = new Book();
book.setName("JPA");
book.setPrice(10000);
book.setStockQuantity(10);
itemRepository.save(book);
em.flush();

#   Hibernate: select next value for item_seq
#   Hibernate: 
#       insert into item (name, price, stock_quantity, author, isbn,
#                         dtype, item_id)
#       values (?, ?, ?, ?, ?, 'B', ?)

#   persist 로 갔다

# --- 수정 (id 가 있음) ---

Book detached = new Book();
detached.setId(1L);
detached.setName("수정된 제목");
detached.setPrice(20000);
detached.setStockQuantity(5);
detached.setAuthor("김영한");
detached.setIsbn("123");

itemRepository.save(detached);
em.flush();

#   Hibernate: 
#       select i1_0.item_id, i1_0.dtype, i1_0.name, i1_0.price,
#              i1_0.stock_quantity, i1_0.actor, i1_0.artist, i1_0.author,
#              i1_0.director, i1_0.etc, i1_0.isbn
#       from item i1_0 where i1_0.item_id=?

#   merge 가 먼저 select 를 날렸다

#   Hibernate: 
#       update item set name=?, price=?, stock_quantity=?, author=?, isbn=?
#       where item_id=?
#   binding parameter [1] as [VARCHAR] - [수정된 제목]
#   binding parameter [2] as [INTEGER] - [20000]
#   binding parameter [3] as [INTEGER] - [5]

#   select + update. 두 개다.

# --- 일부만 채우고 저장하면 ---

Book partial = new Book();
partial.setId(1L);
partial.setName("제목만 바꿈");
// 나머지를 안 채웠다

itemRepository.save(partial);
em.flush();

#   Hibernate: select i1_0.item_id, ... from item i1_0 where i1_0.item_id=?
#   Hibernate: 
#       update item set name=?, price=?, stock_quantity=?, author=?, isbn=?
#       where item_id=?
#   binding parameter [1] as [VARCHAR] - [제목만 바꿈]
#   binding parameter [2] as [INTEGER] - [0]
#   binding parameter [3] as [INTEGER] - [0]
#   binding parameter [4] as [VARCHAR] - [null]
#   binding parameter [5] as [VARCHAR] - [null]

select price, stock_quantity, author from item where item_id = 1;
#   0  0  null

#   가격과 재고가 0 이 되고 저자가 사라졌다

#   「DB 2편」 7.3절의 그 사고다

# --- 반환값을 안 쓰면 ---

itemRepository.save(detached);      // save 가 void 다
detached.setName("또 바꿈");
em.flush();

#   (update 가 안 나간다)

#   detached 는 여전히 준영속이다
#   merge 가 반환한 객체가 영속이었는데 버렸다

# --- 변경 감지로 하면 ---

Item item = itemRepository.findOne(1L);

#   Hibernate: select i1_0.item_id, ... from item i1_0 where i1_0.item_id=?

item.change("수정된 제목", 20000, 5);
em.flush();

#   Hibernate: 
#       update item set name=?, price=?, stock_quantity=?, author=?, isbn=?
#       where item_id=?

#   select 하나 + update 하나
#   개수는 같은데 안 채운 필드가 안 날아간다

# --- findAll ---

itemRepository.findAll();

#   Hibernate: 
#       select i1_0.item_id, i1_0.dtype, i1_0.name, i1_0.price,
#              i1_0.stock_quantity, i1_0.actor, i1_0.artist, i1_0.author,
#              i1_0.director, i1_0.etc, i1_0.isbn
#       from item i1_0

#   조인이 없다
#   SINGLE_TABLE 이라서다 (3.5절)

#   JOINED 였다면 left join 셋이 붙었을 것이다
